operation.add:
		// NeoSeo SSL response - start
			$domain = parse_url(HTTP_SERVER);
			$domain['host'] = str_replace("www.","",$domain['host']);
			if ($_SERVER['HTTPS'] || $_SERVER['HTTP_X_FORWARDED_PROTO'] == 'https') {
			    $this->output = str_replace("http://www.".$domain['host'],"https://www.".$domain['host'],$this->output);
			    $this->output = str_replace("http://".$domain['host'],"https://".$domain['host'],$this->output);
            } else {
			    $this->output = str_replace("https://www.".$domain['host'],"http://www.".$domain['host'],$this->output);
			    $this->output = str_replace("https://".$domain['host'],"http://".$domain['host'],$this->output);
            }
			// NeoSeo SSL response - end
